        locale_t old_lc_ctype, c_lc_ctype;

        c_lc_ctype = newlocale(LC_CTYPE_MASK, "C", 0);
        assert(c_lc_ctype != NULL);
        old_lc_ctype = uselocale(c_lc_ctype);
